<?php require 'includes/functions.php';require_login();$pdo=db();$action=$_GET['action']??$_POST['action']??'';$id=(int)($_GET['id']??$_POST['id']??0);if($action==='add'&&$id){$pdo->prepare('INSERT IGNORE INTO wishlist(user_id,product_id) VALUES(?,?)')->execute([user()['id'],$id]);flash('success','Product added to wishlist.');go('wishlist.php');}if($action==='remove'&&$id){$pdo->prepare('DELETE FROM wishlist WHERE user_id=? AND product_id=?')->execute([user()['id'],$id]);flash('success','Wishlist item removed.');go('wishlist.php');}$q=$pdo->prepare('SELECT p.* FROM wishlist w JOIN products p ON p.id=w.product_id WHERE w.user_id=? ORDER BY w.created_at DESC');$q->execute([user()['id']]);$items=$q->fetchAll();$pageTitle='Wishlist';require 'includes/header.php';require 'includes/navbar.php'; ?>
<main class="container my-5"><h1 class="section-title">My wishlist</h1><div class="row g-3"><?php foreach($items as $p): ?><div class="col-6 col-md-3"><div class="card product-card"><img src="<?=base(e($p['image']))?>" class="product-image"><div class="card-body"><h6><?=e($p['name'])?></h6><b><?=money(product_price($p))?></b><div class="mt-2"><a class="btn btn-dark btn-sm" href="<?=base('product-details.php?id='.$p['id'])?>">Select size</a><a class="btn btn-outline-danger btn-sm" href="<?=base('wishlist.php?action=remove&id='.$p['id'])?>">Remove</a></div></div></div></div><?php endforeach ?></div><?php if(!$items): ?><div class="alert alert-secondary">Your wishlist is empty.</div><?php endif ?></main><?php require 'includes/footer.php'; ?>
